package akogen.fabric.v6;
import java.io.*;import java.nio.file.*;import java.util.*;import java.awt.image.*;import javax.imageio.*;
/** Builds thumbnails from the exact same posed geometry and UVs used in the game. */
public final class PreviewGenerator{
 static final int SIZE=192;static class Tri{double[] p;Tri(double[] p){this.p=p;}}
 public static void main(String[] args)throws Exception{Assets.load(Files.readAllBytes(Paths.get(args[0])));Path out=Paths.get(args[1]);Files.createDirectories(out);for(Assets.Entry e:Assets.entries){if(args.length>2&&e.id!=Integer.parseInt(args[2]))continue;Models.Model model=Models.load(e);Expr.Context ctx=new Expr.Context();ctx.time=2.2;ctx.ownerDistance=2;model.activeAnimations=Models.active(model,ctx,false);Map<String,Models.Mat> done=new HashMap<String,Models.Mat>();BufferedImage texture=ImageIO.read(new ByteArrayInputStream(Assets.files.get(Assets.path(Assets.texture(e.config.get("texture"))))));if(texture==null)throw new IOException("Texture decode failed for "+e.name);List<Tri> triangles=new ArrayList<Tri>();double minX=1e20,maxX=-1e20,minY=1e20,maxY=-1e20;Models.Mat camera=new Models.Mat().rot(-10,28,0);
 for(Models.Bone b:model.bones){Models.Mat mat=camera.mul(Models.pose(model,b,ctx,false,done,0,0));for(float[] face:b.faces){double[][] pts=new double[4][6];for(int i=0;i<4;i++){int k=i*8;double[] p=mat.point(face[k],face[k+1],face[k+2]);pts[i][0]=p[0];pts[i][1]=-p[1];pts[i][2]=p[2];pts[i][3]=face[k+6];pts[i][4]=face[k+7];double nx=mat.m[0]*face[k+3]+mat.m[4]*face[k+4]+mat.m[8]*face[k+5],ny=mat.m[1]*face[k+3]+mat.m[5]*face[k+4]+mat.m[9]*face[k+5],nz=mat.m[2]*face[k+3]+mat.m[6]*face[k+4]+mat.m[10]*face[k+5];double n=Math.sqrt(nx*nx+ny*ny+nz*nz);pts[i][5]=.64+.36*Math.max(0,(ny*.7-nz*.6-nx*.2)/Math.max(.001,n));minX=Math.min(minX,p[0]);maxX=Math.max(maxX,p[0]);minY=Math.min(minY,-p[1]);maxY=Math.max(maxY,-p[1]);}for(int[] ii:new int[][]{{0,1,2},{0,2,3}}){double[] tri=new double[18];for(int i=0;i<3;i++)System.arraycopy(pts[ii[i]],0,tri,i*6,6);triangles.add(new Tri(tri));}}}
 if(triangles.isEmpty()||!Double.isFinite(minX))throw new IOException("Empty model: "+e.name);double scale=Math.min((SIZE-18)/Math.max(.01,maxX-minX),(SIZE-18)/Math.max(.01,maxY-minY)),ox=SIZE/2d-(minX+maxX)/2*scale,oy=SIZE/2d-(minY+maxY)/2*scale;BufferedImage image=new BufferedImage(SIZE,SIZE,BufferedImage.TYPE_INT_ARGB);double[] depth=new double[SIZE*SIZE];Arrays.fill(depth,Double.POSITIVE_INFINITY);
 for(Tri triangle:triangles){double[] t=triangle.p;double ax=t[0]*scale+ox,ay=t[1]*scale+oy,bx=t[6]*scale+ox,by=t[7]*scale+oy,cx=t[12]*scale+ox,cy=t[13]*scale+oy,den=(by-cy)*(ax-cx)+(cx-bx)*(ay-cy);if(Math.abs(den)<1e-8)continue;int x0=Math.max(0,(int)Math.floor(Math.min(ax,Math.min(bx,cx)))),x1=Math.min(SIZE-1,(int)Math.ceil(Math.max(ax,Math.max(bx,cx)))),y0=Math.max(0,(int)Math.floor(Math.min(ay,Math.min(by,cy)))),y1=Math.min(SIZE-1,(int)Math.ceil(Math.max(ay,Math.max(by,cy))));for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){double a=((by-cy)*(x+.5-cx)+(cx-bx)*(y+.5-cy))/den,b=((cy-ay)*(x+.5-cx)+(ax-cx)*(y+.5-cy))/den,c=1-a-b;if(a<0||b<0||c<0)continue;double z=a*t[2]+b*t[8]+c*t[14];int index=y*SIZE+x;if(z>=depth[index])continue;double u=a*t[3]+b*t[9]+c*t[15],v=a*t[4]+b*t[10]+c*t[16],light=a*t[5]+b*t[11]+c*t[17];int tx=Math.max(0,Math.min(texture.getWidth()-1,(int)(u*texture.getWidth()))),ty=Math.max(0,Math.min(texture.getHeight()-1,(int)(v*texture.getHeight())));int color=texture.getRGB(tx,ty),alpha=(color>>>24)&255;if(alpha<32)continue;int r=(int)(((color>>16)&255)*light),g=(int)(((color>>8)&255)*light),bb=(int)((color&255)*light);image.setRGB(x,y,(alpha<<24)|(r<<16)|(g<<8)|bb);depth[index]=z;}}
 ImageIO.write(image,"PNG",out.resolve(e.id+".png").toFile());System.out.println("PREVIEW "+e.id+" "+e.name+" / "+model.activeAnimations+" / "+triangles.size()+" triangles");}
 // Meaningful regression checks: a real flight controller must produce separated, animated geometry.
 for(Assets.Entry e:Assets.entries)if(e.name.equals("Flying Chikita Rei")||e.name.equals("Geass Wings")||e.name.equals("Geass Aura")){Models.Model m=Models.load(e);Expr.Context c=new Expr.Context();c.time=0;List<String> active=Models.active(m,c,false);if(!active.contains(e.name.startsWith("Flying")?"flight":"main"))throw new AssertionError(e.name+" controller not active");m.activeAnimations=active;double delta=0;for(Models.Bone b:m.bones)if(!b.faces.isEmpty()){Models.Mat a=Models.pose(m,b,c,false,new HashMap<String,Models.Mat>(),0,0);c.time=1;Models.Mat bb=Models.pose(m,b,c,false,new HashMap<String,Models.Mat>(),0,0);float[] f=b.faces.get(0);double[] p=a.point(f[0],f[1],f[2]),q=bb.point(f[0],f[1],f[2]);delta+=Math.abs(p[0]-q[0])+Math.abs(p[1]-q[1])+Math.abs(p[2]-q[2]);c.time=0;}if(delta<.001)throw new AssertionError(e.name+" pose is static");System.out.println("ANIMATION PASS "+e.name+" delta="+delta);}
 }
}
